const rows = $input.all().map(r => r.json);

// Deduplicate: keep only the latest record for each pool
const poolMap = {};
for (const r of rows) {
  const key = r.pool_address;
  if (!poolMap[key] || new Date(r.createdAt) > new Date(poolMap[key].createdAt)) {
    poolMap[key] = r;
  }
}
const uniquePools = Object.values(poolMap);

// Sort by creation time descending
const sorted = uniquePools.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

// Stats
const total = sorted.length;
const lowRisk = sorted.filter(r => r.risk_level === 'Low').length;
const mediumRisk = sorted.filter(r => r.risk_level === 'Medium').length;
const highRisk = sorted.filter(r => r.risk_level === 'High').length;
const criticalRisk = sorted.filter(r => r.risk_level === 'Critical').length;

// Pools added in the last hour
const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
const recentPools = sorted.filter(r => new Date(r.created_at) > oneHourAgo).length;

// Relative time formatter
function relativeTime(iso) {
  const now = new Date();
  const d = new Date(iso);
  const diffMs = now - d;
  const diffSec = Math.floor(diffMs / 1000);
  const diffMin = Math.floor(diffMs / 60000);
  const diffHour = Math.floor(diffMs / 3600000);
  const diffDay = Math.floor(diffMs / 86400000);

  if (diffSec < 60) return 'just now';
  if (diffMin < 60) return diffMin + ' min ago';
  if (diffHour < 24) return diffHour + ' hr ago';
  return diffDay + ' days ago';
}

function formatTime(iso) {
  const d = new Date(iso);
  return {
    utc: d.toLocaleString('en-US', { timeZone: 'UTC', hour12: false }),
    la: d.toLocaleString('en-US', { timeZone: 'America/Los_Angeles', hour12: false })
  };
}

// Pool cards
const poolCards = sorted.slice(0, 30).map(r => {
  const t = formatTime(r.created_at);
  const rel = relativeTime(r.created_at);

  const riskColor = r.risk_level === 'Critical' ? '#ef4444' :
                    r.risk_level === 'High' ? '#f97316' :
                    r.risk_level === 'Medium' ? '#eab308' : '#10b981';

  const liqText = r.liquidity >= 1000000 ? '$' + (r.liquidity / 1000000).toFixed(2) + 'M'
    : r.liquidity >= 1000 ? '$' + (r.liquidity / 1000).toFixed(1) + 'K'
    : '$' + r.liquidity.toFixed(2);

  const volText = r.volume_24h >= 1000000 ? '$' + (r.volume_24h / 1000000).toFixed(2) + 'M'
    : r.volume_24h >= 1000 ? '$' + (r.volume_24h / 1000).toFixed(1) + 'K'
    : '$' + r.volume_24h.toFixed(2);

  const feeBadge = r.fee_tier && r.fee_tier !== 'N/A'
    ? '<span class="fee-badge">' + r.fee_tier + '</span>'
    : '';

  return '<div class="pool-card" style="border-left: 4px solid ' + riskColor + ';">' +
    '<div class="card-header">' +
    '<div class="pair-name">' + r.token0_symbol + ' <span class="slash">/</span> ' + r.token1_symbol + feeBadge + '</div>' +
    '<div class="card-time">' +
    '<div class="time-rel">' + rel + '</div>' +
    '<div class="time-abs">UTC ' + t.utc + '</div>' +
    '</div>' +
    '</div>' +
    '<div class="pool-info">' +
    '<div class="info-row"><span>Pool</span><a href="https://www.geckoterminal.com/base/pools/' + r.pool_address + '" target="_blank" class="pool-link">' + (r.pool_address ? r.pool_address.slice(0, 10) + '...' : 'N/A') + '</a></div>' +
    '<div class="info-row"><span>Liquidity</span><strong class="liquidity">' + liqText + '</strong></div>' +
    '<div class="info-row"><span>24h Volume</span><strong class="volume">' + volText + '</strong></div>' +
    '<div class="info-row"><span>Tx Count</span><strong>' + r.tx_count + '</strong></div>' +
    '<div class="info-row"><span>Risk Score</span><strong style="color:' + riskColor + ';">' + r.risk_score + '/100</strong></div>' +
    '</div>' +
    '<div class="risk-banner" style="background:' + riskColor + '20; color:' + riskColor + '; border:1px solid ' + riskColor + ';">' + (r.risk_label || '') + '</div>' +
    '</div>';
}).join('');

const html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta http-equiv="refresh" content="30">' +
'<title>Uniswap New Pool Monitor</title>' +
'<style>' +
'* { box-sizing: border-box; margin: 0; padding: 0; }' +
'body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #0f1117; color: #e5e7eb; padding: 24px; }' +
'.top-bar { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 24px; }' +
'h1 { color: #f59e0b; font-size: 24px; margin-bottom: 4px; }' +
'.subtitle { color: #9ca3af; font-size: 14px; }' +
'.badge { display: inline-block; background: #232733; color: #f59e0b; padding: 4px 12px; border-radius: 6px; font-size: 12px; margin-left: 8px; }' +
'.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 16px; margin-bottom: 24px; }' +
'.stat-card { background: #1a1d27; border-radius: 12px; padding: 18px; }' +
'.stat-label { color: #9ca3af; font-size: 12px; margin-bottom: 6px; }' +
'.stat-value { font-size: 26px; font-weight: 700; color: #f59e0b; }' +
'.stat-value.green { color: #10b981; }' +
'.stat-value.yellow { color: #eab308; }' +
'.stat-value.orange { color: #f97316; }' +
'.stat-value.red { color: #ef4444; }' +
'.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(360px, 1fr)); gap: 20px; }' +
'.pool-card { background: #1a1d27; border-radius: 12px; padding: 18px; }' +
'.card-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 14px; }' +
'.pair-name { color: #60a5fa; font-size: 16px; font-weight: 600; }' +
'.pair-name .slash { color: #6b7280; font-weight: 400; }' +
'.fee-badge { display: inline-block; background: #232733; color: #9ca3af; font-size: 11px; padding: 2px 8px; border-radius: 4px; margin-left: 8px; font-weight: 500; }' +
'.card-time { text-align: right; }' +
'.time-rel { color: #10b981; font-size: 12px; font-weight: 600; margin-bottom: 2px; }' +
'.time-abs { color: #6b7280; font-size: 10px; }' +
'.pool-info { display: flex; flex-direction: column; gap: 8px; }' +
'.info-row { display: flex; justify-content: space-between; font-size: 13px; color: #9ca3af; }' +
'.info-row strong { color: #e5e7eb; }' +
'.info-row .liquidity { color: #10b981; }' +
'.info-row .volume { color: #f59e0b; }' +
'.pool-link { color: #60a5fa; text-decoration: none; font-size: 12px; font-family: monospace; }' +
'.pool-link:hover { text-decoration: underline; }' +
'.risk-banner { padding: 8px 12px; border-radius: 6px; margin-top: 14px; font-size: 12px; font-weight: 600; text-align: center; }' +
'.updated { color: #6b7280; font-size: 12px; margin-top: 24px; text-align: center; }' +
'@media (max-width: 600px) { .grid { grid-template-columns: 1fr; } .stats { grid-template-columns: repeat(2, 1fr); } }' +
'</style></head><body>' +

'<div class="top-bar">' +
'<div>' +
'<h1>🦄 Uniswap New Pool Monitor <span class="badge">Base</span></h1>' +
'<div class="subtitle">Real-time new pool monitoring · Risk scoring · Auto-refresh every 30s</div>' +
'</div>' +
'</div>' +

'<div class="stats">' +
'<div class="stat-card"><div class="stat-label">Total Pools</div><div class="stat-value">' + total + '</div></div>' +
'<div class="stat-card"><div class="stat-label">Last 1h New</div><div class="stat-value green">' + recentPools + '</div></div>' +
'<div class="stat-card"><div class="stat-label">Low Risk</div><div class="stat-value green">' + lowRisk + '</div></div>' +
'<div class="stat-card"><div class="stat-label">Medium Risk</div><div class="stat-value yellow">' + mediumRisk + '</div></div>' +
'<div class="stat-card"><div class="stat-label">High Risk</div><div class="stat-value orange">' + highRisk + '</div></div>' +
'<div class="stat-card"><div class="stat-label">Critical Risk</div><div class="stat-value red">' + criticalRisk + '</div></div>' +
'</div>' +

'<div class="grid">' + poolCards + '</div>' +

'<div class="updated">Last Updated: ' + new Date().toLocaleString('en-US', { timeZone: 'UTC' }) + ' (UTC) · Auto-refresh every 30s</div>' +

'</body></html>';

return [{ json: { html } }];

const data = $input.first().json;
const pools = data.data || [];

const MAJOR_TOKENS = ['USDC', 'USDT', 'WETH', 'ETH', 'WBTC', 'DAI', 'BUSD', 'USDE', 'USDG'];

// 从 name 中提取代币符号和费率，例如 "IOF / WETH 0.3%"
function parsePoolName(name) {
  const parts = (name || '').split(' / ');
  const raw0 = (parts[0] || '').trim();
  const raw1 = (parts[1] || '').trim();

  // 从第二部分里提取费率（如 "WETH 0.3%" → "WETH" + "0.3%"）
  const feeMatch = raw1.match(/\s+([\d.]+%)$/);
  const fee = feeMatch ? feeMatch[1] : 'N/A';
  const token1 = feeMatch ? raw1.replace(feeMatch[0], '').trim() : raw1;

  return {
    token0: raw0,
    token1: token1,
    fee: fee
  };
}

return pools
  .map(pool => {
    const attrs = pool.attributes || {};
    const liquidity = parseFloat(attrs.reserve_in_usd || 0);
    const volume24h = parseFloat(attrs.volume_usd?.h24 || 0);
    const txCount = (attrs.transactions?.h24?.buys || 0) + (attrs.transactions?.h24?.sells || 0);
    const createdAt = attrs.pool_created_at || new Date().toISOString();

    const parsed = parsePoolName(attrs.name);
    const token0Symbol = parsed.token0;
    const token1Symbol = parsed.token1;
    const feeTier = parsed.fee;

    let riskScore = 0;
    if (liquidity < 1000) riskScore += 50;
    else if (liquidity < 10000) riskScore += 30;
    else if (liquidity < 100000) riskScore += 10;

    if (volume24h < 100) riskScore += 30;
    else if (volume24h < 1000) riskScore += 15;

    if (txCount < 10) riskScore += 20;
    else if (txCount < 100) riskScore += 10;

    let riskLevel = 'Low';
    let riskLabel = '✅ Low Risk';
    if (riskScore >= 60) { riskLevel = 'Critical'; riskLabel = '⛔ Critical Risk'; }
    else if (riskScore >= 40) { riskLevel = 'High'; riskLabel = '⚠️ High Risk'; }
    else if (riskScore >= 20) { riskLevel = 'Medium'; riskLabel = '⚡ Medium Risk'; }

    return {
      json: {
        pool_address: attrs.address || 'N/A',
        token0_symbol: token0Symbol,
        token0_address: '',
        token1_symbol: token1Symbol,
        token1_address: '',
        fee_tier: feeTier,
        liquidity: liquidity,
        volume_24h: volume24h,
        tx_count: txCount,
        created_at: createdAt,
        risk_score: riskScore,
        risk_level: riskLevel,
        risk_label: riskLabel,
        network: 'base'
      }
    };
  })
  .filter(p => {
    const t0 = p.json.token0_symbol.toUpperCase();
    const t1 = p.json.token1_symbol.toUpperCase();
    return !(MAJOR_TOKENS.includes(t0) && MAJOR_TOKENS.includes(t1));
  })
  .filter(p => p.json.liquidity >= 500);
